contracts/AgentBestiary.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/common/ERC2981.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Strings.sol";
import "@openzeppelin/contracts/utils/Base64.sol";

interface IAgentRegistry {
    function balanceOf(address wallet) external view returns (uint256);
    function handleOf(address wallet) external view returns (string memory);
}

/// @title Agent Bestiary — .ai-gated creatures, fully on-chain art, lazy seed.
contract AgentBestiary is ERC721, ERC2981, ReentrancyGuard {
    using Strings for uint256;

    uint256 public constant MAX_SUPPLY = 2222;
    uint256 public constant MAX_PER_WALLET = 3;
    uint256 public constant FREE_QUOTA = 500;

    uint256 public immutable price;
    uint256 public immutable revealBlock;
    bytes32 public immutable commitment;
    address payable public immutable treasury;
    IAgentRegistry public immutable registry;

    uint256 public totalMinted;
    uint256 public freeMinted;
    bytes32 public seed;

    mapping(address => uint256) public mintedBy;
    mapping(uint256 => string) internal _handle;

    event Minted(address indexed minter, uint256 indexed tokenId, uint256 paid, string handle);
    event Revealed(bytes32 seed, bool usedBlockhash);

    constructor(
        address registry_,
        address payable treasury_,
        uint256 price_,
        uint256 revealBlock_,
        bytes32 commitment_
    ) ERC721("Agent Bestiary", "BEAST") {
        registry = IAgentRegistry(registry_);
        treasury = treasury_;
        price = price_;
        revealBlock = revealBlock_;
        commitment = commitment_;
        _setDefaultRoyalty(treasury_, 250);
    }

    // ---------------------------------------------------------------- mint

    function quote(address wallet) public view returns (uint256) {
        if (mintedBy[wallet] >= MAX_PER_WALLET) return type(uint256).max;
        if (freeMinted < FREE_QUOTA && mintedBy[wallet] == 0) return 0;
        return price;
    }

    function hasAgentId(address wallet) public view returns (bool) {
        try registry.balanceOf(wallet) returns (uint256 b) {
            return b > 0;
        } catch {
            return false;
        }
    }

    function mint() external payable nonReentrant returns (uint256 tokenId) {
        require(hasAgentId(msg.sender), "No Agent ID");
        require(totalMinted < MAX_SUPPLY, "Sold out");
        require(mintedBy[msg.sender] < MAX_PER_WALLET, "Wallet limit");

        uint256 cost = quote(msg.sender);
        require(msg.value >= cost, "Underpaid");

        if (cost == 0) {
            freeMinted += 1;
        } else {
            (bool toTreasury, ) = treasury.call{value: cost}("");
            require(toTreasury, "Treasury transfer failed");
        }
        if (msg.value > cost) {
            (bool refund, ) = msg.sender.call{value: msg.value - cost}("");
            require(refund, "Refund failed");
        }

        tokenId = ++totalMinted;
        mintedBy[msg.sender] += 1;
        string memory h = registry.handleOf(msg.sender);
        _handle[tokenId] = h;

        _safeMint(msg.sender, tokenId);
        emit Minted(msg.sender, tokenId, cost, h);
    }

    // -------------------------------------------------------------- reveal

    /// Anyone holding the secret can reveal once the target block has passed.
    /// If blockhash(revealBlock) already expired (0), seed falls back to the
    /// secret alone — same rule, stated honestly instead of silently breaking.
    function reveal(bytes32 secret) external {
        require(seed == bytes32(0), "Already revealed");
        require(block.number > revealBlock, "Too early");
        require(keccak256(abi.encodePacked(secret)) == commitment, "Bad secret");
        bytes32 bh = blockhash(revealBlock);
        seed = keccak256(abi.encodePacked(bh, secret));
        emit Revealed(seed, bh != bytes32(0));
    }

    function revealed() public view returns (bool) {
        return seed != bytes32(0);
    }

    // -------------------------------------------------------------- traits

    function _roll(uint256 tokenId, uint8 slot, uint8 mod) internal view returns (uint8) {
        if (seed == bytes32(0)) return 0;
        return uint8(uint256(keccak256(abi.encodePacked(seed, tokenId, slot))) % mod);
    }

    string[4] internal SPECIES = ["pengu", "moth", "squid", "gecko"];
    string[5] internal EYES = ["dot", "visor", "sleepy", "laser", "monocle"];
    string[5] internal HEAD = ["none", "mohawk", "horns", "antenna", "crown"];
    string[4] internal EXTRA = ["none", "halo", "scarf", "orb"];
    string[5] internal BG = ["void", "dusk", "acid", "ember", "mint"];

    string[5] internal BGCOL = ["#0b0b0f", "#1b1730", "#16261a", "#2a1210", "#0f2624"];

    function traits(uint256 tokenId)
        public
        view
        returns (uint8 species, uint8 eyes, uint8 head, uint8 extra, uint8 bg)
    {
        require(tokenId > 0 && tokenId <= totalMinted, "No token");
        species = _roll(tokenId, 1, 4);
        eyes = _roll(tokenId, 2, 5);
        head = _roll(tokenId, 3, 5);
        extra = _roll(tokenId, 4, 4);
        bg = _roll(tokenId, 5, 5);
    }

    /// Lower is rarer. Rarity = product of the chances of each rolled slot.
    function rarityScore(uint256 tokenId) public view returns (uint256) {
        (uint8 s, uint8 e, uint8 h, uint8 x, uint8 b) = traits(tokenId);
        if (!revealed()) return 0;
        // slots: 4*5*5*4*5 = 2000 combos; weight rare indexes higher
        uint256 score = (uint256(s) + 1) * (uint256(e) + 1) * (uint256(h) + 1)
            * (uint256(x) + 1) * (uint256(b) + 1);
        return score;
    }

    function tierOf(uint256 tokenId) public view returns (string memory) {
        require(revealed(), "Sealed");
        (uint8 s, uint8 e, uint8 h, uint8 x, uint8 b) = traits(tokenId);
        uint8 rare;
        if (s >= 2) rare++;
        if (e >= 3) rare++;
        if (h >= 2) rare++;
        if (x >= 2) rare++;
        if (b >= 3) rare++;
        if (rare >= 4) return "Legendary";
        if (rare == 3) return "Epic";
        if (rare == 2) return "Rare";
        if (rare == 1) return "Uncommon";
        return "Common";
    }

    // ----------------------------------------------------------------- art

    function _svg(uint256 tokenId) internal view returns (string memory) {
        (uint8 s, uint8 e, uint8 h, uint8 x, uint8 b) = traits(tokenId);
        string memory body = string.concat(
            '<rect x="128" y="176" width="256" height="256" rx="52" fill="#e9edf5"/>',
            '<rect x="128" y="176" width="256" height="256" rx="52" fill="url(#g)" opacity="0.25"/>',
            '<ellipse cx="196" cy="440" rx="46" ry="16" fill="#e9edf5"/>',
            '<ellipse cx="316" cy="440" rx="46" ry="16" fill="#e9edf5"/>'
        );
        string memory eyes = _eyesSvg(e);
        string memory headPart = _headSvg(h, s);
        string memory extra = _extraSvg(x);
        string memory frame = string.concat(
            '<rect width="512" height="512" fill="', BGCOL[b], '"/>',
            '<defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1">',
            '<stop offset="0" stop-color="#8fd3ff"/><stop offset="1" stop-color="#c39bff"/>',
            "</linearGradient></defs>"
        );
        return string.concat(
            '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512">',
            frame, body, eyes, headPart, extra,
            '<text x="256" y="496" font-family="monospace" font-size="22" fill="#7c8698" text-anchor="middle">',
            "#", tokenId.toString(), " / ", _handle[tokenId], "</text>",
            "</svg>"
        );
    }

    function _eyesSvg(uint8 e) internal pure returns (string memory) {
        if (e == 1) return '<rect x="176" y="268" width="160" height="34" rx="17" fill="#0b0b0f"/><rect x="196" y="278" width="60" height="10" rx="5" fill="#5ce1e6"/>';
        if (e == 2) return '<path d="M180 286 q28 22 56 0" stroke="#0b0b0f" stroke-width="10" fill="none"/><path d="M276 286 q28 22 56 0" stroke="#0b0b0f" stroke-width="10" fill="none"/>';
        if (e == 3) return '<circle cx="206" cy="284" r="18" fill="#ff3b3b"/><circle cx="306" cy="284" r="18" fill="#ff3b3b"/><circle cx="206" cy="284" r="6" fill="#fff"/><circle cx="306" cy="284" r="6" fill="#fff"/>';
        if (e == 4) return '<circle cx="206" cy="284" r="26" fill="#0b0b0f"/><circle cx="306" cy="284" r="26" fill="none" stroke="#0b0b0f" stroke-width="8"/><circle cx="306" cy="284" r="12" fill="#5ce1e6"/>';
        return '<circle cx="206" cy="284" r="22" fill="#0b0b0f"/><circle cx="306" cy="284" r="22" fill="#0b0b0f"/><circle cx="212" cy="277" r="7" fill="#fff"/><circle cx="312" cy="277" r="7" fill="#fff"/>';
    }

    function _headSvg(uint8 h, uint8 s) internal pure returns (string memory) {
        if (h == 1) return '<path d="M186 180 l24 -46 l22 40 l22 -46 l24 46" fill="#ff6b6b"/>';
        if (h == 2) return '<path d="M176 186 l-14 -46 l40 18 z" fill="#c39bff"/><path d="M336 186 l14 -46 l-40 18 z" fill="#c39bff"/>';
        if (h == 3) return '<line x1="256" y1="176" x2="256" y2="128" stroke="#5ce1e6" stroke-width="8"/><circle cx="256" cy="120" r="12" fill="#5ce1e6"/>';
        if (h == 4) return '<path d="M196 170 l20 -38 l20 26 l20 -40 l20 40 l20 -26 l20 38 z" fill="#ffd166"/>';
        if (s == 3) return '<circle cx="256" cy="176" r="12" fill="#8fd3ff" opacity="0.6"/>';
        return "";
    }

    function _extraSvg(uint8 x) internal pure returns (string memory) {
        if (x == 1) return '<ellipse cx="256" cy="126" rx="70" ry="14" fill="none" stroke="#ffd166" stroke-width="8"/>';
        if (x == 2) return '<path d="M168 400 q88 44 176 0 l0 30 q-88 44 -176 0 z" fill="#ff6b6b"/>';
        if (x == 3) return '<circle cx="392" cy="368" r="26" fill="#5ce1e6" opacity="0.85"/>';
        return "";
    }

    function tokenURI(uint256 tokenId) public view override returns (string memory) {
        require(tokenId > 0 && tokenId <= totalMinted, "No token");
        (uint8 s, uint8 e, uint8 h, uint8 x, uint8 b) = traits(tokenId);
        string memory json = string.concat(
            '{"name":"Bestiary #', tokenId.toString(),
            '","description":"Agent Bestiary - on-chain creatures owned by .ai Agent IDs.",',
            '"image":"data:image/svg+xml;base64,', Base64.encode(bytes(_svg(tokenId))), '",',
            '"attributes":[',
            '{"trait_type":"State","value":"', revealed() ? "Revealed" : "Sealed", '"},',
            '{"trait_type":"Species","value":"', SPECIES[s], '"},',
            '{"trait_type":"Eyes","value":"', EYES[e], '"},',
            '{"trait_type":"Head","value":"', HEAD[h], '"},',
            '{"trait_type":"Extra","value":"', EXTRA[x], '"},',
            '{"trait_type":"Background","value":"', BG[b], '"},',
            '{"trait_type":"Tier","value":"', revealed() ? tierOf(tokenId) : "Sealed", '"},',
            '{"trait_type":"Agent","value":"', _handle[tokenId], '"}',
            "]}"
        );
        return string.concat("data:application/json;base64,", Base64.encode(bytes(json)));
    }

    function supportsInterface(bytes4 id) public view override(ERC721, ERC2981) returns (bool) {
        return super.supportsInterface(id);
    }
}

contracts/BestiaryMarket.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/// @title Bestiary Market — two-sided market: asks AND bids, 2% fee to treasury.
contract BestiaryMarket is ReentrancyGuard {
    struct Listing {
        address seller;
        uint96 price;
        uint64 expiry;
    }

    struct Bid {
        address bidder;
        uint96 amount;
        uint64 expiry;
    }

    IERC721 public immutable nft;
    address payable public immutable treasury;
    uint96 public constant FEE_BPS = 200;
    uint256 public constant MIN_PRICE = 0.0001 ether;

    mapping(uint256 => Listing) public listings;
    mapping(uint256 => Bid) public bids;

    event Listed(uint256 indexed tokenId, address indexed seller, uint256 price, uint256 expiry);
    event ListingCancelled(uint256 indexed tokenId);
    event Sold(uint256 indexed tokenId, address indexed buyer, address indexed seller, uint256 price, uint256 fee);
    event BidPlaced(uint256 indexed tokenId, address indexed bidder, uint256 amount, uint256 expiry);
    event BidCancelled(uint256 indexed tokenId, address indexed bidder);
    event BidAccepted(uint256 indexed tokenId, address indexed bidder, address indexed seller, uint256 amount, uint256 fee);

    constructor(address nft_, address payable treasury_) {
        nft = IERC721(nft_);
        treasury = treasury_;
    }

    // ------------------------------------------------------------- asks

    function list(uint256 tokenId, uint256 price, uint256 daysOpen) external {
        require(price >= MIN_PRICE, "Price too low");
        require(daysOpen >= 1 && daysOpen <= 90, "Bad duration");
        require(nft.ownerOf(tokenId) == msg.sender, "Not owner");
        require(
            nft.getApproved(tokenId) == address(this) || nft.isApprovedForAll(msg.sender, address(this)),
            "Not approved"
        );
        // a seller's ask cancels their own standing bid
        _clearBid(tokenId);

        uint64 expiry = uint64(block.timestamp + daysOpen * 1 days);
        listings[tokenId] = Listing(msg.sender, uint96(price), expiry);
        emit Listed(tokenId, msg.sender, price, expiry);
    }

    function cancelListing(uint256 tokenId) external {
        Listing memory l = listings[tokenId];
        require(l.seller == msg.sender, "Not seller");
        delete listings[tokenId];
        emit ListingCancelled(tokenId);
    }

    function buy(uint256 tokenId) external payable nonReentrant {
        Listing memory l = listings[tokenId];
        require(l.seller != address(0), "Not listed");
        require(block.timestamp <= l.expiry, "Expired");
        require(msg.value == l.price, "Wrong value");
        require(nft.ownerOf(tokenId) == l.seller, "Seller moved token");
        require(
            nft.getApproved(tokenId) == address(this) || nft.isApprovedForAll(l.seller, address(this)),
            "Approval gone"
        );

        delete listings[tokenId];
        _clearBid(tokenId);

        uint256 fee = (uint256(l.price) * FEE_BPS) / 10_000;
        _pay(treasury, fee);
        _pay(payable(l.seller), uint256(l.price) - fee);
        nft.safeTransferFrom(l.seller, msg.sender, tokenId);

        emit Sold(tokenId, msg.sender, l.seller, l.price, fee);
    }

    // ------------------------------------------------------------- bids

    function bid(uint256 tokenId) external payable nonReentrant {
        require(msg.value >= MIN_PRICE, "Bid too low");
        require(nft.ownerOf(tokenId) != msg.sender, "Owner cannot bid");
        Bid memory current = bids[tokenId];
        require(msg.value > current.amount, "Bid too small");

        bids[tokenId] = Bid(msg.sender, uint96(msg.value), uint64(block.timestamp + 7 days));
        if (current.bidder != address(0)) _pay(payable(current.bidder), current.amount);
        emit BidPlaced(tokenId, msg.sender, msg.value, uint64(block.timestamp + 7 days));
    }

    function cancelBid(uint256 tokenId) external nonReentrant {
        Bid memory b = bids[tokenId];
        require(b.bidder == msg.sender, "Not bidder");
        delete bids[tokenId];
        _pay(payable(msg.sender), b.amount);
        emit BidCancelled(tokenId, msg.sender);
    }

    /// Seller accepts the standing bid: needs approval, gets paid in the same tx.
    function acceptBid(uint256 tokenId) external nonReentrant {
        Bid memory b = bids[tokenId];
        require(b.bidder != address(0), "No bid");
        require(block.timestamp <= b.expiry, "Bid expired");
        require(nft.ownerOf(tokenId) == msg.sender, "Not owner");
        require(
            nft.getApproved(tokenId) == address(this) || nft.isApprovedForAll(msg.sender, address(this)),
            "Not approved"
        );

        delete bids[tokenId];
        delete listings[tokenId];

        uint256 fee = (uint256(b.amount) * FEE_BPS) / 10_000;
        _pay(treasury, fee);
        _pay(payable(msg.sender), uint256(b.amount) - fee);
        nft.safeTransferFrom(msg.sender, b.bidder, tokenId);

        emit BidAccepted(tokenId, b.bidder, msg.sender, b.amount, fee);
    }

    // ------------------------------------------------------------ views

    function floor() external view returns (uint256) {
        // kept for UI symmetry; concrete floor is computed off-chain over listings
        return MIN_PRICE;
    }

    function listingOf(uint256 tokenId) external view returns (Listing memory, bool live) {
        Listing memory l = listings[tokenId];
        live = l.seller != address(0) && block.timestamp <= l.expiry;
    }

    function bidOf(uint256 tokenId) external view returns (Bid memory, bool live) {
        Bid memory b = bids[tokenId];
        live = b.bidder != address(0) && block.timestamp <= b.expiry;
    }

    // ----------------------------------------------------------- internal

    function _clearBid(uint256 tokenId) internal {
        Bid memory b = bids[tokenId];
        if (b.bidder != address(0)) {
            delete bids[tokenId];
            _pay(payable(b.bidder), b.amount);
            emit BidCancelled(tokenId, b.bidder);
        }
    }

    function _pay(address payable to, uint256 amount) internal {
        if (amount == 0) return;
        (bool ok, ) = to.call{value: amount}("");
        require(ok, "Payment failed");
    }
}

